CREATE TABLE partner_companies ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"name" text NOT NULL,"logo_url" text,"billing_email" text,"billing_phone" text,"billing_address" text,"status" text,"notes" text,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
CREATE TABLE weddings ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"client_id" integer,"venue_name" text NOT NULL,"venue_address" text,"wedding_date" timestamp with time zone NOT NULL,"coordinator_name" text,"coordinator_phone" text,"coordinator_email" text,"special_instructions" text,"package_price" numeric,"payment_status" text,"payment_date" timestamp with time zone,"payment_method" text,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
CREATE TABLE tour_participants ("id" serial NOT NULL PRIMARY KEY,"appointment_id" integer NOT NULL,"participant_type" text NOT NULL,"client_id" integer,"name" text NOT NULL,"phone" text,"email" text,"pickup_location" text,"dropoff_location" text,"created_at" timestamp with time zone);
CREATE TABLE tour_itinerary ("id" serial NOT NULL PRIMARY KEY,"appointment_id" integer NOT NULL,"sequence_order" integer NOT NULL,"location" text NOT NULL,"description" text,"created_at" timestamp with time zone);
